    // syn_CD8_C1.TPDL1 = (CD8_PDL1_total / A_Tcell) * syn_CD8_C1
    _species_var[SP_syn_CD8_C1_TPDL1] = (PARAM(P_CD8_PDL1_total) / PARAM(P_A_Tcell)) * PARAM(P_syn_CD8_C1);
